def valid_round_parentheses(text):
    balance = 0
    for character in text:
        if character == "(":
            balance += 1
        elif character == ")":
            balance -= 1
            if balance < 0:
                return False
    return balance == 0

def is_balanced(text):
    expected_open = {")": "(", "]": "[", "}": "{"}
    stack = []
    for character in text:
        if character in expected_open.values():
            stack.append(character)
        elif character in expected_open:
            if not stack or stack.pop() != expected_open[character]:
                return False
    return not stack

print(is_balanced("{[()]}"))  # True

import heapq

def largest_k(values, k):
    if k <= 0:
        return []
    heap = []
    for value in values:
        if len(heap) < k:
            heapq.heappush(heap, value)
        elif value > heap[0]:
            heapq.heapreplace(heap, value)
    return sorted(heap, reverse=True)

print(largest_k([7, 2, 9, 4, 8], 3))  # [9, 8, 7]

import heapq

def top_students(records, k):
    candidates = []
    for sequence, record in enumerate(records):
        entry = (record["score"], -sequence, record["name"])
        if len(candidates) < k:
            heapq.heappush(candidates, entry)
        elif entry > candidates[0]:
            heapq.heapreplace(candidates, entry)
    return sorted(candidates, reverse=True)

records = [{"name": "Amy", "score": 90}, {"name": "Bo", "score": 85}]
print(top_students(records, 1))

def next_greater(values):
    answers = [-1] * len(values)
    stack = []
    for index, value in enumerate(values):
        while stack and values[stack[-1]] < value:
            previous = stack.pop()
            answers[previous] = value
        stack.append(index)
    return answers

print(next_greater([2, 1, 4, 3]))  # [4, 4, -1, -1]

from collections import deque

def sliding_maximum(values, k):
    if not 1 <= k <= len(values):
        raise ValueError("k 必須介於 1 與資料長度之間")
    candidates = deque()
    answers = []
    for index, value in enumerate(values):
        while candidates and index - candidates[0] >= k:
            candidates.popleft()
        while candidates and values[candidates[-1]] <= value:
            candidates.pop()
        candidates.append(index)
        if index >= k - 1:
            answers.append(values[candidates[0]])
    return answers

print(sliding_maximum([1, 3, -1, -3, 5, 3, 6, 7], 3))
# [3, 3, 5, 5, 6, 7]
